window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6b64437ae3632303"]={"versions": [{"id": "FIG-6b64437ae3632303", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Feature-Modell / Feature-Tree (FODA-Notation / Feature-Oriented Domain Analysis) gemäß AUTOSAR Foundation (<code>AUTOSAR_FO_TR_Features</code>, Release R24-11).</li>\n<li><strong>Technischer Zweck:</strong> Formale Spezifikation der funktionalen Variabilität und Dekomposition von Systemfähigkeiten auf Architekturebene. Es ordnet das standardisierte Fahrzeug-Ladeprotokoll ISO 15118-2 hierarchisch in die übergeordnete Ladedomäne ein.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten (Feature-Knoten):</strong></li>\n<li><code>FO_TR_FEAT_00205</code> (<code>Charging</code>): Übergeordnetes Domänen-Feature (Parent Feature) für Ladefunktionalitäten des Gesamtfahrzeugs (EV-Ladeschnittstellen, AC/DC-Ladekoordination).</li>\n<li><code>FO_TR_FEAT_00206</code> (<code>ISO15118_2</code>): Kind-Feature (Child Feature) zur Kapselung der Protokollimplementierung nach ISO 15118-2 (<em>Road vehicles — Vehicle to grid communication interface — Part 2: Network and application protocol requirements</em>).</li>\n<li><strong>Beziehungen & Semantik:</strong></li>\n<li><strong>Dekompositionskante mit leerem Kreis (Hollow Circle):</strong> Kennzeichnet eine <strong>optionale Abhängigkeit</strong> (<em>optional sub-feature</em>, Kardinalität <code>0..1</code>).</li>\n<li><code>FO_TR_FEAT_00206</code> ist nicht zwingender Bestandteil von <code>FO_TR_FEAT_00205</code>. Ein System mit Ladefunktionalität kann implementiert werden, ohne ISO 15118-2 zu unterstützen (z. B. bei Beschränkung auf reine Basic-PWM-Signalisierung nach IEC 61851-1, DIN 70121, CHAdeMO, GB/T oder ISO 15118-20).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\">\n<li><strong>Statisches Struktur-/Variabilitätsmodell:</strong> Das Diagramm enthält keine Laufzeitsequenzen, Zustände oder Callbacks.</li>\n<li><strong>Funktionaler Kontext bei Aktivierung von <code>FO_TR_FEAT_00206</code>:</strong></li>\n<li>Bindung des V2G-Kommunikationsablaufs über IPv6/TCP und TLS via HomePlug GreenPHY (Ethernet-Subsystem: <code>Eth</code>, <code>EthTrcv</code>, <code>EthIf</code>).</li>\n<li>Protokollphasen: <code>SupportedAppProtocolReq/Res</code> $\\rightarrow$ <code>SessionSetup</code> $\\rightarrow$ Service- und Parameter-Discovery $\\rightarrow$ Authentifizierung / Autorisierung (EIM oder Plug 'n Charge via <code>Csm</code>/<code>CryIf</code>) $\\rightarrow$ Target-Setting / Ladekontrollschleife $\\rightarrow$ Session-Termination.</li>\n<li>Asynchrone Fehlerbehandlung (z. B. TLS-Handshake-Fehler, EXI-Decodierungsfehler, Sequence-Timeouts) über Dem-Events und Det-Fehlercodes der beteiligten Kommunikationsmodule.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Variabilitätsmanagement (ARXML):</strong></li>\n<li>Die optionale Bindung erfordert im AUTOSAR-System- und Software-Design saubere Variantenbildung über <code>VariationPoint</code>-Mechanismen (Post-Build- oder Pre-Compile-Varianz).</li>\n<li>Applikations-SWCs (z. B. Charging Manager) dürfen keine harten Compile-Abhängigkeiten auf ISO 15118-2-spezifische Datentypen oder Schnittstellen erzwingen, wenn <code>FO_TR_FEAT_00205</code> ohne <code>FO_TR_FEAT_00206</code> konfiguriert wird.</li>\n<li><strong>Classic Platform (CP) Stack-Auswirkungen:</strong></li>\n<li>Bei Aktivierung müssen BSW-Module wie <code>V2G</code>, <code>SoAd</code>, <code>TcpIp</code>, <code>EthIf</code>, <code>Csm</code> (für Zertifikats- und Signaturprüfungen nach SECC/EVCC) und der EXI-Parser/Codec im BSW-Stack instantiiert und konfiguriert werden.</li>\n<li><strong>Adaptive Platform (AP) Stack-Auswirkungen:</strong></li>\n<li>Anbindung an Adaptive Applications über ara::com (Service-Interface-Bereitstellung für V2G-Datenstrukturen) und ara::crypto (Schlüssel- und Zertifikatsmanagement für ISO 15118 PnC).</li>\n</ul>"}, {"id": "FIG-1ed1846b8f823375", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Feature-Modell / Feature-Tree (FODA-Notation / Feature-Oriented Domain Analysis) gemäß AUTOSAR Foundation (<code>AUTOSAR_FO_TR_Features</code>, Release R24-11).</li>\n<li><strong>Technischer Zweck:</strong> Formale Spezifikation der funktionalen Variabilität und Dekomposition von Systemfähigkeiten auf Architekturebene. Es ordnet das standardisierte Fahrzeug-Ladeprotokoll ISO 15118-2 hierarchisch in die übergeordnete Ladedomäne ein.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten (Feature-Knoten):</strong></li>\n<li><code>FO_TR_FEAT_00205</code> (<code>Charging_Protocol</code>): Übergeordnetes Domänen-Feature (Parent Feature) für Ladeprotokoll-Funktionalitäten des Fahrzeugs.</li>\n<li><code>FO_TR_FEAT_00206</code> (<code>ISO15118_2</code>): Kind-Feature (Child Feature) zur Kapselung der Protokollimplementierung nach ISO 15118-2 (<em>Road vehicles — Vehicle to grid communication interface — Part 2: Network and application protocol requirements</em>).</li>\n<li><strong>Beziehungen & Semantik:</strong></li>\n<li><strong>Dekompositionskante mit leerem Kreis (Hollow Circle):</strong> Kennzeichnet eine <strong>optionale Abhängigkeit</strong> (<em>optional sub-feature</em>, Kardinalität <code>0..1</code>).</li>\n<li><code>FO_TR_FEAT_00206</code> ist nicht zwingender Bestandteil von <code>FO_TR_FEAT_00205</code>. Ein System mit Ladeprotokoll-Funktionalität kann implementiert werden, ohne ISO 15118-2 zu unterstützen (z. B. bei Beschränkung auf reine Basic-PWM-Signalisierung nach IEC 61851-1, DIN 70121, CHAdeMO, GB/T oder ISO 15118-20).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Statisches Struktur-/Variabilitätsmodell:</strong> Das Diagramm enthält keine Laufzeitsequenzen, Zustände oder Callbacks.</li>\n<li><strong>Funktionaler Kontext bei Aktivierung von <code>FO_TR_FEAT_00206</code>:</strong></li>\n<li>Bindung des V2G-Kommunikationsablaufs über IPv6/TCP und TLS via HomePlug GreenPHY (Ethernet-Subsystem: <code>Eth</code>, <code>EthTrcv</code>, <code>EthIf</code>).</li>\n<li>Protokollphasen: <code>SupportedAppProtocolReq/Res</code> $\\rightarrow$ <code>SessionSetup</code> $\\rightarrow$ Service- und Parameter-Discovery $\\rightarrow$ Authentifizierung / Autorisierung (EIM oder Plug 'n Charge via <code>Csm</code>/<code>CryIf</code>) $\\rightarrow$ Target-Setting / Ladekontrollschleife $\\rightarrow$ Session-Termination.</li>\n<li>Asynchrone Fehlerbehandlung (z. B. TLS-Handshake-Fehler, EXI-Decodierungsfehler, Sequence-Timeouts) über Dem-Events und Det-Fehlercodes der beteiligten Kommunikationsmodule.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Variabilitätsmanagement (ARXML):</strong></li>\n<li>Die optionale Bindung erfordert im AUTOSAR-System- und Software-Design saubere Variantenbildung über <code>VariationPoint</code>-Mechanismen (Post-Build- oder Pre-Compile-Varianz).</li>\n<li>Applikations-SWCs (z. B. Charging Manager) dürfen keine harten Compile-Abhängigkeiten auf ISO 15118-2-spezifische Datentypen oder Schnittstellen erzwingen, wenn <code>FO_TR_FEAT_00205</code> ohne <code>FO_TR_FEAT_00206</code> konfiguriert wird.</li>\n<li><strong>Classic Platform (CP) Stack-Auswirkungen:</strong></li>\n<li>Bei Aktivierung müssen BSW-Module wie <code>V2G</code>, <code>SoAd</code>, <code>TcpIp</code>, <code>EthIf</code>, <code>Csm</code> (für Zertifikats- und Signaturprüfungen nach SECC/EVCC) und der EXI-Parser/Codec im BSW-Stack instantiiert und konfiguriert werden.</li>\n<li><strong>Adaptive Platform (AP) Stack-Auswirkungen:</strong></li>\n<li>Anbindung an Adaptive Applications über ara::com (Service-Interface-Bereitstellung für V2G-Datenstrukturen) und ara::crypto (Schlüssel- und Zertifikatsmanagement für ISO 15118 PnC).</li>\n</ul>"}], "trans": [{"from": "FIG-6b64437ae3632303", "to": "FIG-1ed1846b8f823375", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Feature-Knoten <code>FO_TR_FEAT_00205</code>:</strong> Die Feature-Bezeichnung wurde von <code>Charging</code> in <code>Charging_Protocol</code> umbenannt.</li>\n</ul>"}]};
